MATCH (fa:FlightAccident)-[:involves]->(am:AircraftModel)
WHERE fa.flight_number = "2193" OR fa.name CONTAINS "Pegasus Airlines Flight 2193"
RETURN DISTINCT am.name AS aircraftModelName, am.service_entry AS serviceEntryDate;

MATCH (am:AircraftManufacturer)<-[:manufacturedBy]-(amodel:AircraftModel) 
WHERE amodel.name = "S-92"
RETURN am.name AS manufacturer, am.launch_year AS launch_year;

MATCH (m:AircraftManufacturer {name: "Bombardier"})
MATCH (a:AircraftModel)-[:manufacturedBy]->(m)
RETURN DISTINCT a.name AS model_name;

MATCH (fa:FlightAccident)-[:departsFrom]->(airport:Airport)
WHERE fa.name CONTAINS 'South African Airways Flight 201'
RETURN airport.name AS departedAirportName;
